    for (let c = 0; c < heights[r].length; c++) {
      if (pac.has(r + ',' + c) && atl.has(r + ',' + c)) res.push([r, c]);
    }
  }
  res.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
