def pacificAtlantic(heights):
    if not heights or not heights[0]:
        return []
    R = len(heights)
    def flow_from(starts):
        seen = set(starts)
        stack = list(starts)
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < len(heights[nr]):
                    if (nr, nc) not in seen and heights[nr][nc] >= heights[r][c]:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
        return seen
    pac_starts = [(r, 0) for r in range(R)] + [(0, c) for c in range(len(heights[0]))]
    atl_starts = [(r, len(heights[r]) - 1) for r in range(R)] + [(R - 1, c) for c in range(len(heights[-1]))]
    pac = flow_from(pac_starts)
    atl = flow_from(atl_starts)
    res = [[r, c] for r in range(R) for c in range(len(heights[r])) if (r, c) in pac and (r, c) in atl]
    res.sort()
    return res
